-- Objetivo de cada ODS (texto da Agenda 2030), por idioma, para a janela do ODS na Matriz.
-- 1 a 17: texto oficial (ONU Brasil em PT; ONU em EN/ES). 18: objetivo voluntário do Brasil
-- (texto do ícone oficial em PT; EN/ES = tradução não oficial).
alter table public.ods_refs add column if not exists descricao    text;
alter table public.ods_refs add column if not exists descricao_en text;
alter table public.ods_refs add column if not exists descricao_es text;

update public.ods_refs r set descricao = v.pt, descricao_en = v.en, descricao_es = v.es
from (values
 ('1','Acabar com a pobreza em todas as suas formas, em todos os lugares.','End poverty in all its forms everywhere.','Poner fin a la pobreza en todas sus formas en todo el mundo.'),
 ('2','Acabar com a fome, alcançar a segurança alimentar e melhoria da nutrição e promover a agricultura sustentável.','End hunger, achieve food security and improved nutrition and promote sustainable agriculture.','Poner fin al hambre, lograr la seguridad alimentaria y la mejora de la nutrición y promover la agricultura sostenible.'),
 ('3','Assegurar uma vida saudável e promover o bem-estar para todas e todos, em todas as idades.','Ensure healthy lives and promote well-being for all at all ages.','Garantizar una vida sana y promover el bienestar para todos en todas las edades.'),
 ('4','Assegurar a educação inclusiva e equitativa e de qualidade, e promover oportunidades de aprendizagem ao longo da vida para todas e todos.','Ensure inclusive and equitable quality education and promote lifelong learning opportunities for all.','Garantizar una educación inclusiva, equitativa y de calidad y promover oportunidades de aprendizaje durante toda la vida para todos.'),
 ('5','Alcançar a igualdade de gênero e empoderar todas as mulheres e meninas.','Achieve gender equality and empower all women and girls.','Lograr la igualdad entre los géneros y empoderar a todas las mujeres y las niñas.'),
 ('6','Assegurar a disponibilidade e gestão sustentável da água e saneamento para todas e todos.','Ensure availability and sustainable management of water and sanitation for all.','Garantizar la disponibilidad de agua y su gestión sostenible y el saneamiento para todos.'),
 ('7','Assegurar o acesso confiável, sustentável, moderno e a preço acessível à energia para todas e todos.','Ensure access to affordable, reliable, sustainable and modern energy for all.','Garantizar el acceso a una energía asequible, segura, sostenible y moderna para todos.'),
 ('8','Promover o crescimento econômico sustentado, inclusivo e sustentável, emprego pleno e produtivo e trabalho decente para todas e todos.','Promote sustained, inclusive and sustainable economic growth, full and productive employment and decent work for all.','Promover el crecimiento económico sostenido, inclusivo y sostenible, el empleo pleno y productivo y el trabajo decente para todos.'),
 ('9','Construir infraestruturas resilientes, promover a industrialização inclusiva e sustentável e fomentar a inovação.','Build resilient infrastructure, promote inclusive and sustainable industrialization and foster innovation.','Construir infraestructuras resilientes, promover la industrialización inclusiva y sostenible y fomentar la innovación.'),
 ('10','Reduzir a desigualdade dentro dos países e entre eles.','Reduce inequality within and among countries.','Reducir la desigualdad en los países y entre ellos.'),
 ('11','Tornar as cidades e os assentamentos humanos inclusivos, seguros, resilientes e sustentáveis.','Make cities and human settlements inclusive, safe, resilient and sustainable.','Lograr que las ciudades y los asentamientos humanos sean inclusivos, seguros, resilientes y sostenibles.'),
 ('12','Assegurar padrões de produção e de consumo sustentáveis.','Ensure sustainable consumption and production patterns.','Garantizar modalidades de consumo y producción sostenibles.'),
 ('13','Tomar medidas urgentes para combater a mudança do clima e seus impactos.','Take urgent action to combat climate change and its impacts.','Adoptar medidas urgentes para combatir el cambio climático y sus efectos.'),
 ('14','Conservação e uso sustentável dos oceanos, dos mares e dos recursos marinhos para o desenvolvimento sustentável.','Conserve and sustainably use the oceans, seas and marine resources for sustainable development.','Conservar y utilizar sosteniblemente los océanos, los mares y los recursos marinos para el desarrollo sostenible.'),
 ('15','Proteger, recuperar e promover o uso sustentável dos ecossistemas terrestres, gerir de forma sustentável as florestas, combater a desertificação, deter e reverter a degradação da terra e deter a perda de biodiversidade.','Protect, restore and promote sustainable use of terrestrial ecosystems, sustainably manage forests, combat desertification, and halt and reverse land degradation and halt biodiversity loss.','Proteger, restablecer y promover el uso sostenible de los ecosistemas terrestres, gestionar sosteniblemente los bosques, luchar contra la desertificación, detener e invertir la degradación de las tierras y detener la pérdida de biodiversidad.'),
 ('16','Promover sociedades pacíficas e inclusivas para o desenvolvimento sustentável, proporcionar o acesso à justiça para todos e construir instituições eficazes, responsáveis e inclusivas em todos os níveis.','Promote peaceful and inclusive societies for sustainable development, provide access to justice for all and build effective, accountable and inclusive institutions at all levels.','Promover sociedades pacíficas e inclusivas para el desarrollo sostenible, facilitar el acceso a la justicia para todos y construir a todos los niveles instituciones eficaces e inclusivas que rindan cuentas.'),
 ('17','Fortalecer os meios de implementação e revitalizar a parceria global para o desenvolvimento sustentável.','Strengthen the means of implementation and revitalize the Global Partnership for Sustainable Development.','Fortalecer los medios de implementación y revitalizar la Alianza Mundial para el Desarrollo Sostenible.'),
 ('18','Eliminar o racismo e a discriminação étnico-racial, em todas suas formas, contra os povos indígenas e afrodescendentes.','Eliminate racism and ethnic-racial discrimination, in all its forms, against Indigenous Peoples and people of African descent.','Eliminar el racismo y la discriminación étnico-racial, en todas sus formas, contra los pueblos indígenas y afrodescendientes.')
) as v(num, pt, en, es)
where r.numero = v.num;
